+            return false;
+        }
+        $handle = fopen($path, 'rb');
+        $signature = $handle ? fread($handle, 5) : false;
+        if (is_resource($handle)) {
+            fclose($handle);
+        }
+
+        return $signature === '%PDF-';
+    }
+
+    private function assertReadableFile(string $path, string $message): void
+    {
