+    }
+
+    private function zipEntries(string $path): array
+    {
+        $zip = new ZipArchive;
+        $this->assertTrue($zip->open($path) === true);
+        $entries = [];
+        for ($index = 0; $index < $zip->numFiles; $index++) {
+            $name = $zip->getNameIndex($index);
+            $entries[$name] = $zip->getFromIndex($index);
+        }
+        $zip->close();
+
+        return $entries;
+    }
+
