    11	class FormDvus018DocumentService
    12	{
    13	    public function __construct(private readonly FormDvus018DataMapper $mapper) {}
    14	
    15	    public function generatePdf(EnfAccion $action): string
    16	    {
    17	        $template = (string) config('documents.form_dvus_018_template');
    18	        $this->assertReadableFile($template, 'No se encontró la plantilla maestra FORM-DVUS-018.');
    19	
    20	        $cells = $this->mapper->cells($action);
    21	        $fingerprint = hash('sha256', hash_file('sha256', $template).'|'.json_encode($cells, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
    22	        $cacheDirectory = storage_path('app/generated/form-dvus-018/'.(int) $action->getKey());
    23	        $pdfPath = $cacheDirectory.'/'.$fingerprint.'.pdf';
    24	        $this->ensureDirectory($cacheDirectory);
    25	
    26	        if ($this->isValidPdf($pdfPath)) {
    27	            return $pdfPath;
    28	        }
    29	
    30	        $lockPath = $cacheDirectory.'/.generation.lock';
    31	        $lock = fopen($lockPath, 'c+');
    32	        if ($lock === false || ! flock($lock, LOCK_EX)) {
    33	            throw new RuntimeException('No se pudo bloquear la generación concurrente de FORM-DVUS-018.');
    34	        }
    35	
    36	        try {
    37	            if ($this->isValidPdf($pdfPath)) {
    38	                return $pdfPath;
    39	            }
    40	
    41	            $temporaryDirectory = storage_path('app/tmp/form-dvus-018/'.bin2hex(random_bytes(16)));
    42	            $this->ensureDirectory($temporaryDirectory);
    43	            $docxPath = $temporaryDirectory.'/FORM-DVUS-018.docx';
    44	
    45	            try {
    46	                if (! copy($template, $docxPath)) {
    47	                    throw new RuntimeException('No se pudo copiar la plantilla maestra de FORM-DVUS-018.');
    48	                }
    49	
    50	                $editor = new DocxTemplateEditor($docxPath);
    51	                foreach ($cells as [$table, $row, $cell, $value, $noWrap]) {
    52	                    $editor->setCell($table, $row, $cell, $value, $noWrap);
    53	                }
    54	                $editor->enforceFixedTables()->save();
    55	
    56	                $convertedPdf = $this->convertToPdf($docxPath, $temporaryDirectory);
    57	                $this->validatePdf($convertedPdf);
    58	
    59	                $stagedPath = $cacheDirectory.'/.'.$fingerprint.'.'.bin2hex(random_bytes(6)).'.pdf';
    60	                if (! copy($convertedPdf, $stagedPath) || ! rename($stagedPath, $pdfPath)) {
    61	                    @unlink($stagedPath);
    62	                    throw new RuntimeException('No se pudo publicar el PDF generado de FORM-DVUS-018.');
    63	                }
    64	
    65	                foreach (glob($cacheDirectory.'/*.pdf') ?: [] as $oldPdf) {
    66	                    if ($oldPdf !== $pdfPath) {
    67	                        @unlink($oldPdf);
    68	                    }
    69	                }
    70	            } finally {
    71	                $this->removeDirectory($temporaryDirectory);
    72	            }
    73	
    74	            return $pdfPath;
    75	        } finally {
    76	            flock($lock, LOCK_UN);
    77	            fclose($lock);
    78	        }
    79	    }
    80	
    81	    public function hash(string $pdfPath): string
    82	    {
    83	        $this->assertReadableFile($pdfPath, 'No se puede calcular la huella del PDF FORM-DVUS-018.');
    84	
    85	        return hash_file('sha256', $pdfPath);
    86	    }
    87	
    88	    private function convertToPdf(string $docxPath, string $outputDirectory): string
    89	    {
    90	        $binary = (string) config('documents.libreoffice_binary');
    91	        if (! is_executable($binary)) {
    92	            throw new RuntimeException("LibreOffice no está disponible en {$binary}. Configure LIBREOFFICE_BINARY.");
    93	        }
    94	
    95	        $profileDirectory = $outputDirectory.'/libreoffice-profile';
    96	        $this->ensureDirectory($profileDirectory);
    97	        $profileUri = 'file://'.str_replace('%2F', '/', rawurlencode($profileDirectory));
    98	        $process = new Process([
    99	            $binary,
   100	            '-env:UserInstallation='.$profileUri,
   101	            '--headless',
   102	            '--convert-to',
   103	            'pdf:writer_pdf_Export',
   104	            '--outdir',
   105	            $outputDirectory,
   106	            $docxPath,
   107	        ]);
   108	        $process->setTimeout(180);
   109	        $process->run();
   110	
   111	        if (! $process->isSuccessful()) {
   112	            throw new RuntimeException('LibreOffice no pudo convertir FORM-DVUS-018: '.trim($process->getErrorOutput() ?: $process->getOutput()));
   113	        }
   114	
   115	        $pdfPath = $outputDirectory.'/'.pathinfo($docxPath, PATHINFO_FILENAME).'.pdf';
   116	        if (! $this->isValidPdf($pdfPath)) {
   117	            throw new RuntimeException('LibreOffice finalizó sin crear un PDF válido de FORM-DVUS-018.');
   118	        }
   119	
   120	        return $pdfPath;
   121	    }
   122	
   123	    private function validatePdf(string $pdfPath): void
   124	    {
   125	        $expectedPages = (int) config('documents.form_dvus_018_expected_pages', 11);
   126	        $pdfInfo = (string) config('documents.pdfinfo_binary');
   127	        if (! is_executable($pdfInfo)) {
   128	            return;
   129	        }
   130	
   131	        $process = new Process([$pdfInfo, $pdfPath]);
   132	        $process->setTimeout(30);
   133	        $process->run();
   134	        if (! $process->isSuccessful() || ! preg_match('/^Pages:\s+(\d+)/mi', $process->getOutput(), $match)) {
   135	            throw new RuntimeException('No se pudo validar la cantidad de páginas del PDF FORM-DVUS-018.');
   136	        }
   137	        if ((int) $match[1] !== $expectedPages) {
   138	            throw new RuntimeException("El PDF FORM-DVUS-018 contiene {$match[1]} páginas; se esperaban {$expectedPages}.");
   139	        }
   140	    }
   141	
   142	    private function isValidPdf(string $path): bool
   143	    {
   144	        if (! is_file($path) || filesize($path) < 100) {
   145	            return false;
   146	        }
   147	        $handle = fopen($path, 'rb');
   148	        $signature = $handle ? fread($handle, 5) : false;
   149	        if (is_resource($handle)) {
   150	            fclose($handle);
   151	        }
   152	
   153	        return $signature === '%PDF-';
   154	    }
   155	
   156	    private function assertReadableFile(string $path, string $message): void
   157	    {
   158	        if (! is_file($path) || ! is_readable($path)) {
   159	            throw new RuntimeException($message.' Ruta: '.$path);
   160	        }
   161	    }
   162	
   163	    private function ensureDirectory(string $directory): void
   164	    {
   165	        if (! is_dir($directory) && ! mkdir($directory, 0775, true) && ! is_dir($directory)) {
   166	            throw new RuntimeException("No se pudo crear el directorio {$directory}.");
   167	        }
   168	    }
   169	
   170	    private function removeDirectory(string $directory): void
   171	    {
   172	        if (! is_dir($directory)) {
   173	            return;
   174	        }
   175	        $items = scandir($directory) ?: [];
   176	        foreach ($items as $item) {
   177	            if ($item === '.' || $item === '..') {
   178	                continue;
   179	            }
   180	            $path = $directory.'/'.$item;
   181	            if (is_dir($path) && ! is_link($path)) {
   182	                $this->removeDirectory($path);
   183	            } else {
   184	                @unlink($path);
   185	            }
   186	        }
   187	        @rmdir($directory);
   188	    }
   189	}
