    11	class DocxTemplateEditor
    12	{
    13	    private const WORD_NS = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main';
    14	
    15	    private DOMDocument $document;
    16	
    17	    private DOMXPath $xpath;
    18	
    19	    public function __construct(private readonly string $path)
    20	    {
    21	        $xml = $this->readEntry('word/document.xml');
    22	        $this->document = new DOMDocument('1.0', 'UTF-8');
    23	        $this->document->preserveWhiteSpace = true;
    24	
    25	        if (! $this->document->loadXML($xml, LIBXML_NONET | LIBXML_NOBLANKS)) {
    26	            throw new RuntimeException('La plantilla FORM-DVUS-018 contiene XML inválido.');
    27	        }
    28	
    29	        $this->xpath = new DOMXPath($this->document);
    30	        $this->xpath->registerNamespace('w', self::WORD_NS);
    31	    }
    32	
    33	    public function setCell(int $table, int $row, int $cell, mixed $value, bool $noWrap = false): self
    34	    {
    35	        $target = $this->cell($table, $row, $cell);
    36	        $normalizedValue = $this->normalize($value);
    37	        $this->replaceCellContent($target, $normalizedValue);
    38	
    39	        if ($noWrap) {
    40	            $properties = $this->child($target, 'tcPr', true);
    41	            if (! $this->xpath->query('./w:noWrap', $properties)->item(0)) {
    42	                $properties->appendChild($this->document->createElementNS(self::WORD_NS, 'w:noWrap'));
    43	            }
    44	        }
    45	
    46	        return $this;
    47	    }
    48	
    49	    public function cloneRow(int $table, int $row): int
    50	    {
    51	        $source = $this->row($table, $row);
    52	        $clone = $source->cloneNode(true);
    53	        $source->parentNode?->insertBefore($clone, $source->nextSibling);
    54	
    55	        return $row + 1;
    56	    }
    57	
    58	    public function enforceFixedTables(): self
    59	    {
    60	        foreach ($this->xpath->query('//w:tbl') as $table) {
    61	            if (! $table instanceof DOMElement) {
    62	                continue;
    63	            }
    64	
    65	            // Do not add layout properties that are absent in the master: doing so
    66	            // changes Word's original column calculation. Existing fixed layouts,
    67	            // grids and exact cell widths remain untouched.
    68	            $layout = $this->xpath->query('./w:tblPr/w:tblLayout', $table)->item(0);
    69	            if ($layout instanceof DOMElement && $layout->getAttributeNS(self::WORD_NS, 'type') === 'fixed') {
    70	                $layout->setAttributeNS(self::WORD_NS, 'w:type', 'fixed');
    71	            }
    72	        }
    73	
    74	        return $this;
    75	    }
    76	
    77	    public function save(): void
    78	    {
    79	        $zip = new ZipArchive;
    80	        if ($zip->open($this->path) !== true) {
    81	            throw new RuntimeException("No se pudo escribir el DOCX temporal: {$this->path}");
    82	        }
    83	
    84	        $zip->addFromString('word/document.xml', $this->document->saveXML());
    85	        $zip->close();
    86	    }
    87	
    88	    private function replaceCellContent(DOMElement $cell, string $value): void
    89	    {
    90	        foreach (iterator_to_array($this->xpath->query('.//w:br[not(@w:type="page")]', $cell)) as $break) {
    91	            $break->parentNode?->removeChild($break);
    92	        }
    93	
    94	        $texts = iterator_to_array($this->xpath->query('.//w:t', $cell));
    95	        foreach ($texts as $textNode) {
    96	            while ($textNode->firstChild) {
    97	                $textNode->removeChild($textNode->firstChild);
    98	            }
    99	        }
   100	
   101	        $paragraph = $this->xpath->query('./w:p', $cell)->item(0);
   102	        if (! $paragraph instanceof DOMElement) {
   103	            $paragraph = $this->document->createElementNS(self::WORD_NS, 'w:p');
   104	            $cell->appendChild($paragraph);
   105	        }
   106	        $run = $this->xpath->query('.//w:r', $paragraph)->item(0);
   107	        if (! $run instanceof DOMElement) {
   108	            $run = $this->document->createElementNS(self::WORD_NS, 'w:r');
   109	            $paragraph->appendChild($run);
   110	        }
   111	        $text = $texts[0] ?? null;
   112	        if ($text instanceof DOMElement && $text->parentNode instanceof DOMElement && $text->parentNode->localName === 'r') {
   113	            $run = $text->parentNode;
   114	        } elseif (! $text instanceof DOMElement) {
   115	            $text = $this->document->createElementNS(self::WORD_NS, 'w:t');
   116	            $run->appendChild($text);
   117	        }
