   123	        foreach ($lines as $line) {
   124	            $break = $this->document->createElementNS(self::WORD_NS, 'w:br');
   125	            $nextText = $this->document->createElementNS(self::WORD_NS, 'w:t');
   126	            $nextText->setAttribute('xml:space', 'preserve');
   127	            $nextText->appendChild($this->document->createTextNode($line));
   128	            $run->appendChild($break);
   129	            $run->appendChild($nextText);
   130	        }
   131	
   132	        $width = (int) $this->xpath->evaluate('string(./w:tcPr/w:tcW/@w:w)', $cell);
   133	        $widthType = $this->xpath->evaluate('string(./w:tcPr/w:tcW/@w:type)', $cell);
   134	        $charactersPerLine = $widthType === 'pct'
   135	            ? max(12, (int) floor(95 * $width / 5000))
   136	            : max(12, (int) floor($width / 100));
   137	        $estimatedLines = collect(preg_split('/\R/u', $value) ?: [''])
