   145	            if (! $hasText && ! $hasPageMarker) {
   146	                $candidate->parentNode?->removeChild($candidate);
   147	                $paragraphsToRemove--;
   148	            }
   149	        }
   150	    }
   151	
   152	    private function applyControlledFontSize(DOMElement $run, string $value): void
   153	    {
   154	        $length = mb_strlen($value);
   155	        $halfPoints = str_contains($value, '@')
   156	            ? 14
   157	            : ($length > 600 ? 14 : ($length > 300 ? 16 : null));
   158	        if ($halfPoints === null) {
   159	            return;
   160	        }
   161	
   162	        $properties = $this->child($run, 'rPr', true);
   163	        foreach (['sz', 'szCs'] as $name) {
   164	            $size = $this->xpath->query('./w:'.$name, $properties)->item(0);
   165	            if (! $size instanceof DOMElement) {
   166	                $size = $this->document->createElementNS(self::WORD_NS, 'w:'.$name);
   167	                $properties->appendChild($size);
   168	            }
   169	            $size->setAttributeNS(self::WORD_NS, 'w:val', (string) $halfPoints);
   170	        }
   171	    }
   172	
   173	    private function cell(int $table, int $row, int $cell): DOMElement
   174	    {
   175	        $targetRow = $this->row($table, $row);
   176	        $target = $this->xpath->query('./w:tc', $targetRow)->item($cell - 1);
   177	        if (! $target instanceof DOMElement) {
   178	            throw new RuntimeException("No existe la celda {$table}:{$row}:{$cell} en la plantilla FORM-DVUS-018.");
   179	        }
   180	
   181	        return $target;
   182	    }
   183	
   184	    private function row(int $table, int $row): DOMElement
   185	    {
   186	        $targetTable = $this->xpath->query('//w:body/w:tbl')->item($table - 1);
   187	        $target = $targetTable ? $this->xpath->query('./w:tr', $targetTable)->item($row - 1) : null;
   188	        if (! $target instanceof DOMElement) {
   189	            throw new RuntimeException("No existe la fila {$table}:{$row} en la plantilla FORM-DVUS-018.");
   190	        }
   191	
   192	        return $target;
   193	    }
   194	
   195	    private function child(DOMElement $parent, string $name, bool $prepend): DOMElement
   196	    {
   197	        $existing = $this->xpath->query('./w:'.$name, $parent)->item(0);
   198	        if ($existing instanceof DOMElement) {
   199	            return $existing;
   200	        }
   201	
   202	        $child = $this->document->createElementNS(self::WORD_NS, 'w:'.$name);
   203	        if ($prepend && $parent->firstChild) {
   204	            $parent->insertBefore($child, $parent->firstChild);
   205	        } else {
   206	            $parent->appendChild($child);
   207	        }
   208	
   209	        return $child;
   210	    }
   211	
   212	    private function normalize(mixed $value): string
   213	    {
   214	        return trim(preg_replace("/\r\n?|\u{2028}|\u{2029}/u", "\n", (string) ($value ?? '')) ?? '');
   215	    }
   216	
   217	    private function readEntry(string $entry): string
   218	    {
   219	        $zip = new ZipArchive;
   220	        if ($zip->open($this->path) !== true) {
   221	            throw new RuntimeException("No se pudo abrir la plantilla DOCX: {$this->path}");
   222	        }
   223	        $contents = $zip->getFromName($entry);
   224	        $zip->close();
   225	        if (! is_string($contents)) {
   226	            throw new RuntimeException("La plantilla DOCX no contiene {$entry}.");
   227	        }
   228	
   229	        return $contents;
   230	    }
